// a table's "Player"/"Winner" value is sometimes the raw join-key name (Ash, Paddy),
// sometimes the "MDE"-suffixed display name (Ash MDE, Paddy MDE), and sometimes (the
// Green Jacket's Big Dog/2nd/3rd columns, from 2006 on) a name with that year's score
// trailing it in parentheses ("Paddy (106)") - photos are keyed by the bare raw name,
// so all of that gets stripped before looking one up.
function photoFor(name){
  if (name == null) return null;
  var n = String(name).trim().replace(/\s*\([^)]*\)\s*$/, '').replace(/\s+MDE$/, '').trim();
  return PLAYER_PHOTOS[n] || null;
}
// a small circular headshot + name, for player rows in a bar-list (Explorer
