function avatarLabelHTML(name){
  var photo = photoFor(name);
  return (photo ? '<img class="bar-avatar" src="' + photo + '" alt="">' : '<span class="bar-avatar bar-avatar-blank"></span>') +
    '<span class="bar-avatar-name">' + esc(name) + '</span>';
}
