  retrievers: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M6 10c0-2.8 2.2-5 5-5 .8 0 1.3.4 1.3 1.1 0 .6-.3.9-.9 1.1-1.4.6-2.6 1.9-2.6 3.6M16.5 8.3c1.2.4 2 1.5 2 2.8 0 .9-.4 1.6-1 2.1"/><path d="M8 11.4c-1.2.5-2 1.7-2 3.1 0 2.4 2.4 4 5.4 4h2.6c3.1 0 5.7-1.7 5.7-4.4 0-1.5-.8-2.8-2.1-3.5"/><circle cx="9.8" cy="12.7" r=".85" fill="currentColor" stroke="none"/><path d="M4 15.5c-.8.3-1.4 1-1.4 2"/></svg>'
