function initHeroSpotlight(hero){
  hero.addEventListener('mousemove', function(e){
    var r = hero.getBoundingClientRect();
    hero.style.setProperty('--mx', ((e.clientX - r.left)/r.width*100).toFixed(1) + '%');
    hero.style.setProperty('--my', ((e.clientY - r.top)/r.height*100).toFixed(1) + '%');
  });
}

function animateCount(el, target, suffix){
  var start = 0, dur = 900, t0 = null;
  function step(ts){
    if (!t0) t0 = ts;
    var p = Math.min(1, (ts - t0) / dur);
    var eased = 1 - Math.pow(1 - p, 3);
    el.textContent = Math.round(start + (target - start) * eased) + (suffix||"");
    if (p < 1) requestAnimationFrame(step);
    else el.textContent = target + (suffix||"");
  }
  requestAnimationFrame(step);
}

function esc(s){
  return String(s).replace(/[&<>"]/g, function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];
  });
}

// scrollIntoView({block:'start'}) always aligns an element's top edge to the
// viewport top - fine when the element is shorter than the visible viewport,
// but on a short mobile viewport a tall element (e.g. a player's portrait
// profile card, which runs taller than it is wide) then has its bottom - where
// the trophy rows sit - pushed below the fold, with no further auto-scroll to
// reveal it. Here, if the element fits, behave exactly like block:'start'; if
// it doesn't fit, ask for block:'end' instead, so the element's BOTTOM lands
// at the viewport bottom and the content that would otherwise be cut off (the
// trophy records) is guaranteed visible, at the cost of the heading above it.
// This used to compute that "align the bottom" position by hand (pageYOffset
// + rect.bottom - viewportH), which depends on window.innerHeight correctly
// reporting the visible viewport - inside this nested cross-origin embed on
// mobile that reading is evidently NOT trustworthy, since the hand-computed
// version consistently landed only a quarter of the way down however the
// numbers were adjusted. block:'end' hands the entire alignment over to the
// browser's own native scrollIntoView implementation instead, which has to
// resolve the real scrollable ancestor and its true visible size internally
// regardless of what our own JS can measure - only the fits-or-not decision
// still uses our own viewport read, and getting that wrong just picks the
// less-ideal of the two native alignments rather than landing at an
// arbitrary wrong pixel offset.
function scrollFullyIntoView(el){
  // This page always runs inside a cross-origin Wix embed iframe, which itself
  // sits inside a much taller outer page (the site's own nav/hero above it,
  // more content below). Bringing a profile card fully into view usually means
  // scrolling BOTH this iframe's own internal overflow AND the outer Wix page
  // around the iframe - and scrollIntoView() is the ONLY API that can reach
  // across that iframe boundary at all. (window.scrollTo/scrollBy only ever
  // move *this* document - they cannot move the outer page, which JS in here
  // has no access to at all since it's a different origin. An earlier version
  // of this function tried a same-document window.scrollBy() "nudge" as a
  // safety net, which could never have worked for exactly that reason.)
  // On mobile Safari specifically, a single animated scrollIntoView call across
  // that frame boundary seems to sometimes land short of the target instead of
  // completing the full distance - so this calls it again (a few times if
  // needed) until the element is actually fully in view, rather than trusting
  // one call to have finished the job.
  var attempts = 0;
  function attempt(){
    attempts++;
    var rect = el.getBoundingClientRect();
    var viewportH = window.innerHeight || document.documentElement.clientHeight;
    var block = rect.height <= viewportH ? 'start' : 'end';
    el.scrollIntoView({behavior: attempts === 1 ? 'smooth' : 'auto', block: block});
    if (attempts >= 5) return;
    setTimeout(function(){
      var r = el.getBoundingClientRect();
      var vh = window.innerHeight || document.documentElement.clientHeight;
      var cutOffBottom = r.bottom - vh > 4;
      var cutOffTop = r.top < -4 && block === 'start';
      // Always make at least one more call regardless of what this check finds:
      // this document can only see ITS OWN internal scroll position, never
      // whether the outer Wix page actually finished scrolling this iframe
      // itself into view - so a call that looks complete from in here can
      // still have left the iframe only partly on the phone's physical screen,
      // with no way for us to detect that from inside it. One unconditional
      // extra call gives that cross-frame portion another chance to complete;
      // after that, only keep retrying if our own (limited) view still looks wrong.
      if (attempts === 1 || cutOffBottom || cutOffTop) attempt();
    }, attempts === 1 ? 700 : 300);
  }
  attempt();
}

// A large on-screen debug overlay was used earlier to track down a mobile
// scroll bug - it's since been confirmed (via that overlay's own readout)
// that the auto-scroll correctly lands the full profile card inside the
// viewport, so the overlay itself has been removed rather than left running,
// since a box that size was very likely covering/obscuring the very content
// it was meant to help verify. This still waits one extra layout tick after
// images load before scrolling, cheap insurance against any late reflow.
function afterLayoutSettles(cb){
  requestAnimationFrame(function(){ requestAnimationFrame(cb); });
}

function isNumericCol(rows, idx){
  var n=0, tot=0;
  for (var i=0;i<rows.length && i<60;i++){
    var v = rows[i][idx];
    // "N/A" ("did not play" for a sparse year column, e.g. RC Points/Stableford)
    // is a missing value, not a text value - skip it here the same way blank/null
    // already are, so a column that's mostly N/A but genuinely numeric wherever it
    // does have a value (every real entry there is a number) still gets classed as
    // numeric instead of failing the ratio check and rendering left-aligned as text.
    if (v === "" || v === null || v === undefined || v === "N/A") continue;
    tot++;
    if (typeof v === "number" || (!isNaN(parseFloat(v)) && isFinite(v))) n++;
  }
  return tot>0 && (n/tot) >= 0.7;
}

function cellClass(v, isNum){
  var s = String(v).trim();
  if (s === "Bloodhounds" || s === "BH") return "bh";
  if (s === "Retrievers" || s === "RT") return "rt";
  // a real sentence-like placeholder (e.g. Shitzu's "No record" for 2002-2005, before
  // Stableford scoring existed) reads oddly in the tabular-nums monospace font the
  // rest of its numeric column uses — unlike the short "N/A" token, which already
  // reads fine that way and is left alone — so give it the plain prose font instead,
  // while still centering it under the column like every other value there
  if (s === "No record") return "no-record";
  return isNum ? "num" : "";
}

// Golf-style fraction display: 1.5 -> "1½", 3.25 -> "3¼", 10.75 -> "10¾". Numbers
// with no fractional part, or a fraction other than a quarter/half, are untouched.
var FRACTION_GLYPHS = {'5':'½','25':'¼','75':'¾'};
function toFraction(s){
  return String(s).replace(/(\d+)\.(\d+)/g, function(m, intPart, dec){
    var frac = FRACTION_GLYPHS[dec];
    if (!frac) return m;
    return (intPart === '0' ? '' : intPart) + frac;
  });
}

// Ryder Cup results columns store both sides' score in one cell as "BH - RT" —
// render it as a single colored, fraction-formatted score: red for a Bloodhounds
// win, blue for a Retrievers win, gold for a halved round/tour (or a rain-off).
// For the Final score column, that row's own "Result" text (e.g. "Bloodhounds
// awarded the cup 3 - 5 (decided outside the points)") decides the color rather
// than a raw point comparison — unless forceCls overrides it entirely (2012 is a
// real, further exception: the recorded points went to Retrievers, but the cup
// itself was retained by Bloodhounds via off-tour tie-break matches).
function scoreCellHTML(raw, resultText, forceCls){
  var s = (raw === null || raw === undefined) ? '' : String(raw).trim();
  if (!s) return {html: '', cls: ''};
  var m = s.match(/^(-?\d+(?:\.\d+)?)\s*-\s*(-?\d+(?:\.\d+)?)$/);
  if (!m){
    if (/^rained off$/i.test(s)) return {html: esc(s), cls: 'tie'};
    return {html: esc(s), cls: ''};
  }
  var left = parseFloat(m[1]), right = parseFloat(m[2]);
  var cls = forceCls || null;
  if (!cls && resultText){
    var rt = String(resultText).trim();
    if (/tied/i.test(rt)) cls = 'tie';
    else if (/^bloodhounds/i.test(rt)) cls = 'bh';
    else if (/^retrievers/i.test(rt)) cls = 'rt';
  }
  if (!cls) cls = left > right ? 'bh' : (right > left ? 'rt' : 'tie');
  // the winning side's number leads — BH first for a Bloodhounds win (the data's own
  // order already), RT first for a Retrievers win, BH-then-RT for a halved score
  var bhDisp = toFraction(m[1]), rtDisp = toFraction(m[2]);
  var display = cls === 'rt' ? (rtDisp + ' – ' + bhDisp) : (bhDisp + ' – ' + rtDisp);
  return {html: esc(display), cls: cls};
}
// Columns on the "Results Summary" (Tour by Tour) sheet that hold a "BH - RT" pair.
var SCORE_COLUMNS = {'Round I':1, 'Round II':1, 'Round III':1, 'Final score':1};
// Markers for table footnotes (e.g. "2002*" -> "* Individual stroke play only…"),
// assigned in sequence (*, **, ***…) in order of first appearance, reused whenever
// the same note repeats.
var FOOTNOTE_MARKERS = ['*', '**', '***', '****', '*****'];
// A hand-curated exception to the usual "who had more points" coloring, for tours
// whose outcome wasn't simply decided by the two sides' points — keyed by year.
var FINAL_SCORE_OVERRIDES = {
  2012: {
    cls: 'rt',
    note: 'Retrievers led 5-3 after Round II, but Round III was rained off and a series ' +
      'of off-tour matches were played to decide the result. These matches were halved ' +
      '6-6 so the Bloodhounds retained the Ryder Cup.'
  }
};

// A few extra "global" points/match totals for the Series Summary table, verified
// against the "Ryder Cup Stats" reference document (Comparison of the Bloodhounds
// and the Retrievers, 2004-2026, 23 matches). These need a couple of quirky-year
// house-rule adjustments (halved/abandoned-match treatment) that the auto-generated
// summary block doesn't capture, so they're entered here verbatim rather than derived,
// and spliced into the table's rows right after "Total match points".
var SERIES_SUMMARY_EXTRA_ROWS = [
  ['Matches won (not including halved points)', 170, 193],
  ['Matches halved', 43, 43],
  ['Total four-ball points won (209 matches, 2004–2026)', '90¾', '118¼'],
  ['Total single points won (191 matches, 2005–2026)', 99, 92]
];
var SERIES_SUMMARY_FOOTNOTES = [
  'Matches won by tour — Bloodhounds: 6+3+7+9+10+5+8+8+2+3+10+4+12+7+5+10+5+4+10+9+10+11+12 = 170. ' +
    'Retrievers: 3+9+8+6+6+7+7+6+4+14+10+11+7+8+11+4+9+7+8+9+10+14+15 = 193 ' +
    '(wins awarded for “half” matches in 2025 and 2026).',
  'Matches halved does not include the deemed halves awarded for the abandoned 2012 singles matches.'
];

// Player Records (RC Players): a player who has represented both teams is marked
// with an asterisk and shows his combined record across both — see build_webdata.py's
// DUAL_TEAM_PLAYERS for the same note kept in sync with the data side.
var RC_PLAYERS_FOOTNOTES = [
  "Has also represented the other team on at least one tour — shown here under the team he's most associated with, with his combined record across both."
];

function rowMatches(rowArr, needle){
  if (!needle) return true;
  needle = needle.toLowerCase();
  for (var i=0;i<rowArr.length;i++){
    if (String(rowArr[i]).toLowerCase().indexOf(needle) !== -1) return true;
  }
  return false;
}

function applyFilter(t){
  var per = (t.searchVal||"").toLowerCase();
  var glob = (globalFilterValue||"").toLowerCase();
  var shown = 0;
  for (var i=0;i<t.trRows.length;i++){
    var ok = rowMatches(t.rows[i], per) && rowMatches(t.rows[i], glob);
    t.trRows[i].style.display = ok ? "" : "none";
    if (ok) shown++;
  }
  t.countEl.textContent = shown === t.rows.length ? (t.rows.length + " row" + (t.rows.length===1?"":"s")) :
    (shown + " of " + t.rows.length + " rows");
  t.emptyRow.style.display = shown === 0 ? "" : "none";
}

function buildTable(label, headers, rows, opts){
  opts = opts || {};
  var scoreFormat = !!opts.scoreFormat;
  var noScroll = !!opts.noScroll;
  var hideSet = {};
  (opts.hideColumns || []).forEach(function(h){ hideSet[h] = true; });
  // a column that would otherwise auto-detect as numeric (and so go right-aligned,
  // monospace) but reads better as plain left-aligned text, e.g. a small round count
  var forceTextSet = {};
  (opts.forceTextCols || []).forEach(function(h){ forceTextSet[h] = true; });
  // a column whose content is always short (Yes/No, a small count) — capped so it
  // doesn't stretch to soak up space freed by hiding a wider neighbour
  var narrowSet = {};
  (opts.narrowCols || []).forEach(function(h){ narrowSet[h] = true; });
  // a column short enough to dodge the auto ">14 chars" wrap threshold on its
  // header text alone, but whose values need the same wrapping room as a sibling
  // column that does clear it (e.g. "Round I course" next to "Round II course")
  var wrapSet = {};
  (opts.wrapCols || []).forEach(function(h){ wrapSet[h] = true; });
  // a column whose content is a fixed-width date (e.g. "2026-05-10") — narrower
  // than a free-text column, but needs more room than narrowCols' 92px allows
  // without wrapping onto a second line, and should never wrap
  var dateSet = {};
  (opts.dateCols || []).forEach(function(h){ dateSet[h] = true; });
  // a column that should render at the same fixed width as its siblings regardless
  // of how long its own content happens to be (e.g. a grid of trophy-winner names)
  var eqwSet = {};
  (opts.eqwCols || []).forEach(function(h){ eqwSet[h] = true; });
  // header name -> small image shown inline before the label text (e.g. a trophy icon)
  var headerImages = opts.headerImages || {};
  // a column whose value is a player's name — prefix each cell with that player's
  // circular headshot, when one exists (Players roster, trophy winner columns)
  var avatarSet = {};
  (opts.avatarCols || []).forEach(function(h){ avatarSet[h] = true; });
  // a column holding a percentage (e.g. "58%") - rendered as a small inline
  // proportional bar instead of bare text (Player Records' "Point %")
  var barSet = {};
  (opts.barCols || []).forEach(function(h){ barSet[h] = true; });
  var visibleCount = 0;
  headers.forEach(function(h){ if (!hideSet[h]) visibleCount++; });

  // year-by-year score heatmap (opts.heatmap) - the same value-to-colour mapping used
  // on the Explorer's "Whole Picture" tab (color-mix gold over a global low/high, with
  // a gold ring on that column's own top score), applied here to this table's own bare-
  // 4-digit-year columns so the plain score grids (Three-Round Totals, Round I/II/III)
  // read consistently with the visual one. Computed up-front (rather than down by the
  // header row, where this used to live) purely so its low/high range is known in time
  // to draw the ramp key into the card header below.
  // opts.heatmapInvert flips which end counts as "best" - a finishing position
  // (Placings) is better the LOWER it is, the opposite of a score (Stableford, RC
  // Points), so there the per-column ring marks that column's minimum, not its
  // maximum, and darker gold means a lower number rather than a higher one.
  var heatInvert = !!opts.heatmapInvert;
  var heatColIdxs = [], heatColTop = {}, heatLo = 0, heatHi = 0;
  if (opts.heatmap){
    headers.forEach(function(h, i){ if (/^\d{4}$/.test(String(h).trim())) heatColIdxs.push(i); });
    var heatVals = [];
    heatColIdxs.forEach(function(i){
      var best = null;
      rows.forEach(function(r){
        var v = r[i];
        if (typeof v === 'number'){
          heatVals.push(v);
          if (best === null || (heatInvert ? v < best : v > best)) best = v;
        }
      });
      heatColTop[i] = best;
    });
    if (heatVals.length){ heatLo = Math.min.apply(null, heatVals); heatHi = Math.max.apply(null, heatVals); }
  }

  var card = document.createElement('div');
  card.className = 'table-card' + (opts.spread ? ' spread' : '');
  // lets a "jump to this table" link elsewhere on the page (e.g. RC Records' quick
  // nav) scroll straight to this card — set per block by renderSheet, not per sheet
  if (opts.anchorId) card.id = opts.anchorId;

  var head = document.createElement('div');
  head.className = 'tc-head';
  // a trophy's own photo, in a circle, ahead of the table's heading text — set per
  // sheet in tableOptsFor (the single-trophy tabs)
  if (opts.cardIcon){
    var cardIcon = document.createElement('img');
    cardIcon.className = 'tc-card-icon';
    cardIcon.src = opts.cardIcon;
    cardIcon.alt = '';
    head.appendChild(cardIcon);
  }
  var lab = document.createElement('div');
  lab.className = 'tc-label';
  lab.textContent = label || "";
  var count = document.createElement('div');
  count.className = 'tc-count';
  var search = document.createElement('input');
  search.className = 'tc-search';
  search.type = 'text';
  search.placeholder = 'Search this table…';
  head.appendChild(lab); head.appendChild(count); head.appendChild(search);
  card.appendChild(head);

  // a colour key for the heatmap above, matching the Explorer's "Whole Picture" ramp —
  // without this, the gold shading here has no explanation of its own on this table
  if (opts.heatmap && heatColIdxs.length && heatHi > heatLo){
    var heatKey = document.createElement('div');
    heatKey.className = 'sfx-ramp table-heat-ramp';
    // the gradient always reads faint-to-solid gold left-to-right; which raw number
    // sits at the solid (gold) end flips with heatInvert, so the labels are swapped
    // to match rather than the bar itself
    heatKey.innerHTML = (heatInvert ? esc(heatHi) : esc(heatLo)) + '<span class="rb"></span>' + (heatInvert ? esc(heatLo) : esc(heatHi)) +
      '<span class="heat-key-note">gold ring = that year’s best</span>';
    card.appendChild(heatKey);
  }

  // mirrored scrollbar, sticky near the top of the table (see CSS) so a wide table
  // can be scrolled sideways without hunting for the native scrollbar at its bottom —
  // skipped entirely for a table declared small enough to never need horizontal scroll
  var mirrorWrap, mirror, mirrorInner;
  if (!noScroll){
    mirrorWrap = document.createElement('div');
    mirrorWrap.className = 'scrollbar-mirror-wrap';
    mirror = document.createElement('div');
    mirror.className = 'scrollbar-mirror';
    mirrorInner = document.createElement('div');
    mirrorInner.className = 'scrollbar-mirror-inner';
    mirror.appendChild(mirrorInner);
    mirrorWrap.appendChild(mirror);
    card.appendChild(mirrorWrap);
  }

  // a separate, sticky "frozen header" strip. The header row can't simply stay
  // position:sticky inside the horizontally-scrolling table — a container with
  // overflow-x:auto also becomes an overflow-y container (a CSS quirk), which makes
  // IT the sticky containing block instead of the viewport, so top-stickiness silently
  // never engages. Splitting the header into its own table here, with column widths
  // copied from the real table, and its scroll position synced to it, sidesteps that.
  // Again skipped for noScroll — a short table's plain thead needs no such split.
  var headerWrap, headerScroll;
  if (!noScroll){
    headerWrap = document.createElement('div');
    headerWrap.className = 'sticky-header-wrap';
    headerScroll = document.createElement('div');
    headerScroll.className = 'sticky-header-scroll';
    headerWrap.appendChild(headerScroll);
    card.appendChild(headerWrap);
  }

  var scroll = document.createElement('div');
  scroll.className = 'table-scroll' + (noScroll ? ' no-hscroll' : '');
  var table = document.createElement('table');
  table.className = 'data' + (visibleCount > 10 ? ' dense' : '') + (noScroll ? ' auto-width' : '');
  var isRankCol = headers[0] && String(headers[0]).trim().toLowerCase() === 'rank';
  var thead = document.createElement('thead');
  var trh = document.createElement('tr');
  var numCols = headers.map(function(h,i){ return forceTextSet[h] ? false : isNumericCol(rows, i); });

  headers.forEach(function(h, i){
    if (hideSet[h]) return;
    var th = document.createElement('th');
    // the arrow is positioned absolutely (see CSS), pinned to the header cell itself
    // rather than flowing inline after the label — inline placement let it break away
    // onto its own line once a wrapped label (narrow/wrap columns) filled the last
    // line, and folding it into the label's own line-wrapping would instead widen
    // every such column just to keep the two together
    var iconHtml = headerImages[h] ? '<img class="th-icon" src="' + esc(headerImages[h]) + '" alt="">' : '';
    th.innerHTML = iconHtml + esc(h) + '<span class="arrow">↕</span>';
    if (numCols[i]) th.className = 'num';
    else if ((h.length > 14 || wrapSet[h]) && !narrowSet[h] && !dateSet[h] && !eqwSet[h]) th.className = 'wrap';
    if (narrowSet[h]) th.className = (th.className ? th.className + ' ' : '') + 'narrow';
    // the header label ("Tour start date") is longer than the date values themselves —
    // let it wrap like a narrow column rather than forcing the whole column wide enough
    // to fit the label on one line; the data cells below (date-col) still stay nowrap
    if (dateSet[h]) th.className = (th.className ? th.className + ' ' : '') + 'narrow';
    if (eqwSet[h]) th.className = (th.className ? th.className + ' ' : '') + 'eqw';
    th.addEventListener('click', function(){ sortBy(i); });
    trh.appendChild(th);
  });
  thead.appendChild(trh);
  table.appendChild(thead);

  var resultColIdx = scoreFormat ? headers.indexOf('Result') : -1;
  var finalScoreIdx = scoreFormat ? headers.indexOf('Final score') : -1;
  var yearIdx = scoreFormat ? headers.indexOf('Year') : -1;
  // a one-off asterisk on a specific Year value (e.g. Green Jacket's 2012, whose round
  // was cut short) — opts.yearNotes = {2012: "explanation…"} — rendered with the same
  // footnote marker/list machinery as the scoreFormat case above, just keyed by year
  // rather than by an empty Result.
  var yearNotes = opts.yearNotes || null;
  var yearNoteIdx = yearNotes ? headers.indexOf('Year') : -1;
  // a row with no final score (e.g. a pre-Ryder Cup tour) gets "N/A" in its blank
  // cells and an asterisk-style footnote on its Year, sourced from its own Result text
  var footnoteMap = {}, footnoteList = [];
  function footnoteMarkerFor(text){
    text = text || '';
    if (footnoteMap[text]) return footnoteMap[text];
    var marker = FOOTNOTE_MARKERS[footnoteList.length] || '*';
    footnoteMap[text] = marker;
    footnoteList.push({marker: marker, text: text});
    return marker;
  }

  var tbody = document.createElement('tbody');
  var trRows = rows.map(function(r){
    var tr = document.createElement('tr');
    var isNoTourRow = finalScoreIdx !== -1 && !r[finalScoreIdx];
    r.forEach(function(v, i){
      if (hideSet[headers[i]]) return;
      var td = document.createElement('td');
      var blank = (v === '' || v === null || v === undefined);
      var isScoreCol = scoreFormat && SCORE_COLUMNS[headers[i]];
      var isFinalScoreCol = headers[i] === 'Final score';
      var override = (scoreFormat && isFinalScoreCol && yearIdx !== -1) ? FINAL_SCORE_OVERRIDES[r[yearIdx]] : null;
      var sc = (isScoreCol && !(isNoTourRow && blank)) ?
        scoreCellHTML(v, (isFinalScoreCol && resultColIdx !== -1) ? r[resultColIdx] : null, override ? override.cls : null) : null;
      var cls = cellClass(v, numCols[i]);
      if (sc && sc.cls) cls = (cls === 'num' ? 'num ' : '') + sc.cls;
      var isHeatCell = heatColIdxs.indexOf(i) !== -1 && typeof v === 'number';
      if (isHeatCell){
        var heatFrac = heatInvert ? (heatHi - v) / (heatHi - heatLo) : (v - heatLo) / (heatHi - heatLo);
        var hpct = heatHi > heatLo ? (8 + heatFrac * 92) : 60;
        td.style.background = 'color-mix(in oklab, var(--gold) ' + hpct.toFixed(0) + '%, var(--felt))';
        cls = (cls ? cls + ' ' : '') + 'heat-cell' + (hpct > 55 ? ' heat-hi' : '') + (v === heatColTop[i] ? ' heat-win' : '');
      }
      if (cls) td.className = cls;
      else if (headers[i] && (headers[i].length > 14 || wrapSet[headers[i]]) && !narrowSet[headers[i]] && !dateSet[headers[i]] && !eqwSet[headers[i]]) td.className = 'wrap';
      if (narrowSet[headers[i]]) td.className = (td.className ? td.className + ' ' : '') + 'narrow';
      if (dateSet[headers[i]]) td.className = (td.className ? td.className + ' ' : '') + 'date-col';
      if (eqwSet[headers[i]]) td.className = (td.className ? td.className + ' ' : '') + 'eqw';
      if (i === 0 && isRankCol && (v === 1 || v === 2 || v === 3)){
        var badge = document.createElement('span');
        badge.className = 'rank-badge rank-' + v;
        badge.textContent = v;
        td.appendChild(badge);
      } else if (scoreFormat && isNoTourRow && i === yearIdx){
        var marker = footnoteMarkerFor(resultColIdx !== -1 ? r[resultColIdx] : '');
        td.innerHTML = esc(v) + '<sup class="footnote-ref" title="' + esc(resultColIdx !== -1 ? r[resultColIdx] : '') + '">' + esc(marker) + '</sup>';
      } else if (isNoTourRow && blank){
        td.textContent = 'N/A';
        td.className = (td.className ? td.className + ' ' : '') + 'na-cell';
      } else if (sc){
        td.innerHTML = sc.html;
        if (override){
          var omarker = footnoteMarkerFor(override.note);
          td.innerHTML += '<sup class="footnote-ref" title="' + esc(override.note) + '">' + esc(omarker) + '</sup>';
        }
      } else if (i === yearNoteIdx && yearNotes[v] !== undefined){
        var ymarker = footnoteMarkerFor(yearNotes[v]);
        td.innerHTML = esc(v) + '<sup class="footnote-ref" title="' + esc(yearNotes[v]) + '">' + esc(ymarker) + '</sup>';
      } else if (avatarSet[headers[i]] && !blank){
        // a player-name column: prefix the name with their circular headshot when
        // we have one for them (Players roster, trophy Winner/Big Dog columns) -
        // falls back to plain text silently when no photo matches (e.g. a
        // pre-photo era winner, or a name that isn't a current player). A joint
        // win (e.g. a shared trophy, or a Green Jacket tie for 3rd) is stored as
        // "Name / Name" - " / " (with spaces, so "N/A" itself never splits) - and
        // gets one avatar chip per name, side by side.
        var names = String(v).split(' / ');
        td.className = (td.className ? td.className + ' ' : '') + 'avatar-cell';
        td.innerHTML = '<span class="avatar-multi">' + names.map(function(nm, ni){
          var photo = photoFor(nm);
          return (ni > 0 ? '<span class="avatar-sep">/</span>' : '') +
            '<span class="avatar-wrap">' + (photo ? '<img class="player-avatar" src="' + photo + '" alt="">' : '<span class="player-avatar-blank"></span>') +
            '<span class="avatar-name">' + esc(nm) + '</span></span>';
        }).join('') + '</span>';
      } else if (barSet[headers[i]] && !blank && !isNaN(parseFloat(v))){
        // a percentage value, shown as a small filled bar rather than bare text
        var pct = Math.max(0, Math.min(100, parseFloat(v)));
        td.className = (td.className ? td.className + ' ' : '') + 'pct-cell';
        td.innerHTML = '<span class="pct-bar-wrap"><span class="pct-bar-fill" style="width:' + pct.toFixed(0) + '%"></span>' +
          '<span class="pct-bar-label">' + esc(v) + '</span></span>';
      } else {
        td.textContent = blank ? "" : v;
      }
      tr.appendChild(td);
    });
    tbody.appendChild(tr);
    return tr;
  });
  var emptyRow = document.createElement('tr');
  emptyRow.className = 'empty-row';
  emptyRow.style.display = 'none';
  var etd = document.createElement('td');
  etd.colSpan = visibleCount || 1;
  etd.textContent = 'No rows match your filter.';
  emptyRow.appendChild(etd);
  tbody.appendChild(emptyRow);
  table.appendChild(tbody);
  scroll.appendChild(table);
  card.appendChild(scroll);

  var staticFootnotes = opts.footnotes || [];
  if (footnoteList.length || staticFootnotes.length){
    var fnWrap = document.createElement('div');
    fnWrap.className = 'table-footnotes';
    footnoteList.forEach(function(f){
      var p = document.createElement('p');
      p.innerHTML = '<sup>' + esc(f.marker) + '</sup> ' + esc(f.text);
      fnWrap.appendChild(p);
    });
    // plain source notes for the table as a whole — not tied to a specific cell's
    // marker, so rendered without a superscript reference
    staticFootnotes.forEach(function(text){
      var p2 = document.createElement('p');
      p2.textContent = text;
      fnWrap.appendChild(p2);
    });
    card.appendChild(fnWrap);
  }

  // keep the mirror, the frozen header and the real table scrolled together (three
  // surfaces the reader can drag/swipe: the mirror bar, the header row itself, or the
  // table body), and hide the mirror entirely when the table isn't wide enough to need one —
  // none of this applies to a noScroll table, which keeps its plain, unsplit thead
  if (!noScroll){
    var syncingScroll = false;
    var syncScrollFrom = function(source){
      if (syncingScroll) return;
      syncingScroll = true;
      var x = source.scrollLeft;
      if (source !== mirror) mirror.scrollLeft = x;
      if (source !== scroll) scroll.scrollLeft = x;
      if (source !== headerScroll) headerScroll.scrollLeft = x;
      syncingScroll = false;
    };
    mirror.addEventListener('scroll', function(){ syncScrollFrom(mirror); });
    scroll.addEventListener('scroll', function(){ syncScrollFrom(scroll); });
    headerScroll.addEventListener('scroll', function(){ syncScrollFrom(headerScroll); });

    var headerSplitDone = false;
    var headerTableEl = null, measuredTotalWidth = 0;
    // set only for columns pinned to a declared width (narrow/eqw) — everything else
    // is a flexible column that's free to grow when the table stretches to fill its card
    var pinnedColWidth = null, flexColIdx = null, colsHeadEls = null, colsBodyEls = null;

    // Column widths are fixed in px (see below), but the table's overall width isn't —
    // it's re-applied on every resize as the larger of "what the columns need" and "what
    // the card currently offers", so a table narrower than its card stretches to fill it
    // instead of leaving a gap, while a table that's genuinely too wide still scrolls as
    // before. With no pinned columns that fill-growth is left to the browser's own
    // fixed-layout proportional scaling (unchanged from before); with pinned columns it's
    // done by hand below, growing only the flexible columns, so a narrow/eqw column stays
    // at its declared width no matter how much the rest of the table stretches.
    var applyTableWidth = function(){
      if (!headerTableEl) return;
      var w = Math.max(measuredTotalWidth, scroll.clientWidth);
      if (flexColIdx && flexColIdx.length && w > measuredTotalWidth){
        var extra = (w - measuredTotalWidth) / flexColIdx.length;
        flexColIdx.forEach(function(i){
          var newW = pinnedColWidth[i] + extra;
          if (colsHeadEls[i]) colsHeadEls[i].style.width = newW + 'px';
          if (colsBodyEls[i]) colsBodyEls[i].style.width = newW + 'px';
        });
      }
      table.style.width = w + 'px';
      headerTableEl.style.width = w + 'px';
    };

    var splitHeaderOnce = function(){
      if (headerSplitDone) return;
      if (!table.isConnected || !thead.isConnected) return;
      var ths = trh.querySelectorAll('th');
      if (!ths.length) return;
      var widths = [];
      ths.forEach(function(th){ widths.push(th.getBoundingClientRect().width); });
      if (!widths[0]) return; // not laid out yet
      headerSplitDone = true;

      // a column declared narrow/eqw gets its width fixed to the declared value here,
      // rather than trusting this first measurement — table auto-layout doesn't reliably
      // respect a cell's max-width once the whole table also needs to grow or shrink to
      // fill its card, so the raw measurement can come back either smaller or larger than
      // intended (e.g. an "equal width" column ending up wider than its neighbours). Any
      // slack from the card being wider than the table's natural content then flows only
      // into the remaining, unpinned columns (see applyTableWidth), never into these.
      var baseWidths = widths.map(function(w, i){
        var th = ths[i];
        if (th.classList.contains('eqw')) return 90;
        if (th.classList.contains('narrow')) return 92;
        return w;
      });
      pinnedColWidth = baseWidths;
      flexColIdx = [];
      ths.forEach(function(th, i){
        if (!th.classList.contains('eqw') && !th.classList.contains('narrow')) flexColIdx.push(i);
      });
      // no narrow/eqw column on this table at all - leave fill-growth to the browser's
      // own proportional fixed-layout scaling, exactly as before, rather than switching
      // every column over to the flat equal-px growth used for a table that has one
      if (flexColIdx.length === ths.length) flexColIdx = null;

      // an explicit pixel width (not the table's usual width:100%) on BOTH tables — with
      // width:100%, table-layout:fixed proportionally rescales columns to fit whatever the
      // container happens to offer, and the two containers differ by a scrollbar's worth of
      // width (the header's native scrollbar is hidden, the body's isn't), which was
      // throwing the two tables' column widths out of sync by a few pixels
      var totalWidth = 0;
      baseWidths.forEach(function(w){ totalWidth += w; });
      measuredTotalWidth = totalWidth;

      var headerTable = document.createElement('table');
      headerTable.className = table.className;
      var colgroupHead = document.createElement('colgroup');
      var colgroupBody = document.createElement('colgroup');
      colsHeadEls = []; colsBodyEls = [];
      baseWidths.forEach(function(w){
        var c1 = document.createElement('col'); c1.style.width = w + 'px';
        colgroupHead.appendChild(c1); colsHeadEls.push(c1);
        var c2 = document.createElement('col'); c2.style.width = w + 'px';
        colgroupBody.appendChild(c2); colsBodyEls.push(c2);
      });
      headerTable.appendChild(colgroupHead);
      headerTable.appendChild(thead); // moves the real thead (and its click handlers) out
      headerScroll.appendChild(headerTable);
      headerTableEl = headerTable;

      table.insertBefore(colgroupBody, table.firstChild);
      table.style.tableLayout = 'fixed';
      applyTableWidth();
    };

    var syncMirrorWidth = function(){
      splitHeaderOnce();
      applyTableWidth();
      var sw = table.scrollWidth, cw = scroll.clientWidth;
      mirrorInner.style.width = sw + 'px';
      mirrorWrap.classList.toggle('is-hidden', sw <= cw + 2);
    };
    if (window.ResizeObserver){
      new ResizeObserver(syncMirrorWidth).observe(table);
      new ResizeObserver(syncMirrorWidth).observe(scroll);
    } else {
      window.addEventListener('resize', syncMirrorWidth);
    }
    setTimeout(syncMirrorWidth, 0);
  }

  var tRec = { tbody: tbody, headers: headers, rows: rows, trRows: trRows, searchVal: "", countEl: count, emptyRow: emptyRow,
               table: table, sortCol: -1, sortDir: 1, numCols: numCols };
  allTables.push(tRec);
  applyFilter(tRec);

  search.addEventListener('input', function(){
    tRec.searchVal = search.value;
    applyFilter(tRec);
  });

  function sortBy(colIdx){
    var ths = trh.querySelectorAll('th');
    if (tRec.sortCol === colIdx) tRec.sortDir *= -1; else { tRec.sortCol = colIdx; tRec.sortDir = 1; }
    ths.forEach(function(th){ th.classList.remove('sorted','desc'); });
    ths[colIdx].classList.add('sorted');
    if (tRec.sortDir < 0) ths[colIdx].classList.add('desc');
    var isNum = numCols[colIdx];
    // A column that's mostly "N/A" (most players didn't play most years) fails the
    // 70%-numeric threshold that decides numCols, so it sorts as plain text below —
    // "N/A" needs sinking to the bottom there too, not just in the isNum branch, or
    // it reads as a real value ("N" sorting in among the digits) once reversed.
    function isMissing(v){ return v === null || v === undefined || v === "" || v === "N/A"; }
    var idxs = rows.map(function(_,i){ return i; });
    idxs.sort(function(a,b){
      var va = rows[a][colIdx], vb = rows[b][colIdx];
      var ma = isMissing(va), mb = isMissing(vb);
      // an "N/A"/blank cell always sinks to the bottom of the column, whichever way
      // it's sorted — without this fixed rule, reversing to descending would also
      // reverse the missing-value handling and float every N/A to the top instead
      if (ma || mb){
        if (ma && mb) return 0;
        return ma ? 1 : -1;
      }
      if (isNum){
        return (parseFloat(va) - parseFloat(vb)) * tRec.sortDir;
      }
      var cmp = String(va).localeCompare(String(vb), undefined, {numeric:true, sensitivity:'base'});
      return cmp * tRec.sortDir;
    });
    tbody.innerHTML = "";
    var newRows = [], newTr = [];
    idxs.forEach(function(i){ newRows.push(rows[i]); newTr.push(trRows[i]); tbody.appendChild(trRows[i]); });
    tbody.appendChild(emptyRow);
    tRec.rows = newRows; tRec.trRows = newTr;
    applyFilter(tRec);
  }

  // Most of these sheets list players in the underlying spreadsheet's natural
  // (alphabetical-by-name) order, with a trailing "Rank" column carrying the actual
  // best-to-worst standing — default to that ranking instead, so the table opens
  // already showing who's on top rather than who comes first alphabetically. A
  // leaderboard-style sheet that already leads with its own Pos/Rank column (so its
  // rows arrive pre-sorted from the workbook) is left exactly as it is.
  var firstHeader = headers[0] ? String(headers[0]).trim().toLowerCase() : "";
  var lastIdx = headers.length - 1;
  var lastHeader = headers[lastIdx] ? String(headers[lastIdx]).trim().toLowerCase() : "";
  if (firstHeader !== 'rank' && firstHeader !== 'pos' && lastHeader === 'rank' && numCols[lastIdx]){
    sortBy(lastIdx);
  }

  return card;
}

function svgEl(tag, attrs){
  var el = document.createElementNS('http://www.w3.org/2000/svg', tag);
  for (var k in attrs) el.setAttribute(k, attrs[k]);
  return el;
}

function niceMax(v){
  if (v <= 0) return 1;
  var mag = Math.pow(10, Math.floor(Math.log(v) / Math.LN10));
  var n = v / mag;
  var step = n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10;
  return step * mag;
}

// Horizontal magnitude bars, single hue (gold by default) — for leaderboards / rankings.
// See dataviz guidance: sequential (one hue) is the right color job for "compare magnitude".
function buildBarList(title, subtitle, items, opts){
  opts = opts || {};
  var card = document.createElement('div');
  card.className = 'chart-card fade-in';
  var head = document.createElement('div');
  head.className = 'chart-head';
  head.innerHTML = '<div class="chart-title">' + esc(title) + '</div>' +
    (subtitle ? '<div class="chart-sub">' + esc(subtitle) + '</div>' : '');
  card.appendChild(head);

  var body = document.createElement('div');
  body.className = 'barlist';
  var max = 0;
  items.forEach(function(it){ max = Math.max(max, parseFloat(it.value) || 0); });

  items.forEach(function(it, i){
    var row = document.createElement('div');
    row.className = 'bar-row';
    row.title = it.label + ': ' + it.value + (opts.suffix || '');
    var lbl = document.createElement('div');
    lbl.className = 'bar-label';
    lbl.textContent = it.label;
    var track = document.createElement('div');
    track.className = 'bar-track';
    var fill = document.createElement('div');
    fill.className = 'bar-fill' + (opts.colorClass ? (' ' + opts.colorClass) : '');
    var v = parseFloat(it.value) || 0;
    var pct = max > 0 ? Math.max(4, (v / max) * 100) : 0;
    track.appendChild(fill);
    var val = document.createElement('div');
    val.className = 'bar-value';
    val.textContent = it.value + (opts.suffix || '');
    row.appendChild(lbl); row.appendChild(track); row.appendChild(val);
    body.appendChild(row);
    setTimeout(function(){ fill.style.width = pct + '%'; }, 30 + i * 35);
  });
  card.appendChild(body);
  return card;
}

// Grouped column chart (categorical, 2+ series) — for comparing distinct series across
// categories, e.g. Bloodhounds vs Retrievers scores per tour. Hand-built SVG per the
// dataviz skill: fixed hairline gridlines, thin rounded-top/square-baseline bars,
// a legend (never color-only), and a shared "one tooltip, every series" hover layer.
function buildTrendChart(title, subtitle, categories, seriesDefs){
  var card = document.createElement('div');
  card.className = 'chart-card fade-in';
  var head = document.createElement('div');
  head.className = 'chart-head';
  head.innerHTML = '<div class="chart-title">' + esc(title) + '</div>' +
    (subtitle ? '<div class="chart-sub">' + esc(subtitle) + '</div>' : '');
  card.appendChild(head);

  var legend = document.createElement('div');
  legend.className = 'chart-legend';
  seriesDefs.forEach(function(s){
    var it = document.createElement('span');
    it.className = 'legend-item';
    it.innerHTML = '<span class="legend-swatch ' + s.className + '"></span>' + esc(s.label);
    legend.appendChild(it);
  });
  card.appendChild(legend);

  var wrap = document.createElement('div');
  wrap.className = 'chart-scroll';

  var W = Math.max(560, categories.length * 44), H = 250;
  var padL = 34, padR = 8, padT = 8, padB = 26;
  var plotW = W - padL - padR, plotH = H - padT - padB;

  var maxV = 0;
  categories.forEach(function(c){
    seriesDefs.forEach(function(s){ maxV = Math.max(maxV, parseFloat(c.values[s.id]) || 0); });
  });
  var top = niceMax(maxV);

  var svg = svgEl('svg', {viewBox: '0 0 ' + W + ' ' + H, class: 'trendchart'});
  svg.style.width = W + 'px';
  svg.style.minWidth = '100%';
  svg.style.height = 'auto';

  [0, top / 2, top].forEach(function(t){
    var y = padT + plotH - (t / top) * plotH;
    svg.appendChild(svgEl('line', {x1: padL, x2: W - padR, y1: y, y2: y, class: 'gridline'}));
    var lab = svgEl('text', {x: padL - 6, y: y + 3.5, class: 'axislabel', 'text-anchor': 'end'});
    lab.textContent = Math.round(t * 10) / 10;
    svg.appendChild(lab);
  });

  var groupW = plotW / categories.length;
  var barGap = 3;
  var barW = Math.max(3, Math.min(15, (groupW - barGap * (seriesDefs.length + 1)) / seriesDefs.length));

  var tooltip = document.createElement('div');
  tooltip.className = 'chart-tooltip';
  tooltip.style.display = 'none';
  wrap.appendChild(tooltip);

  categories.forEach(function(c, ci){
    var gx = padL + ci * groupW;
    seriesDefs.forEach(function(s, si){
      var v = parseFloat(c.values[s.id]) || 0;
      if (v <= 0) return;
      var bh = (v / top) * plotH;
      var bx = gx + barGap + si * (barW + barGap);
      var by = padT + plotH - bh;
      var r = Math.min(4, bh);
      svg.appendChild(svgEl('rect', {x: bx, y: by, width: barW, height: Math.max(bh, 1), rx: r, ry: r, class: 'mark ' + s.className}));
      if (r > 0){
        // square off the baseline corners — a mark grows from a flat base, never rounds it
        svg.appendChild(svgEl('rect', {x: bx, y: padT + plotH - r, width: barW, height: r, class: 'mark ' + s.className}));
      }
    });
    if (ci % Math.ceil(categories.length / 18 || 1) === 0 || categories.length <= 18){
      var xl = svgEl('text', {x: gx + groupW / 2, y: H - 8, class: 'axislabel', 'text-anchor': 'middle'});
      xl.textContent = c.label;
      svg.appendChild(xl);
    }
    var hit = svgEl('rect', {x: gx, y: padT, width: groupW, height: plotH, class: 'chart-hit', tabindex: '0'});
    function showTip(){
      var lines = ['<div class="tt-head">' + esc(c.sub || c.label) + '</div>'];
      seriesDefs.forEach(function(s){
        var v = c.values[s.id];
        lines.push('<div class="tt-row"><span class="tt-key ' + s.className + '"></span>' +
          '<span class="tt-val">' + esc(v === undefined || v === '' || v === null ? '—' : v) + '</span>' +
          '<span class="tt-lbl">' + esc(s.label) + '</span></div>');
      });
      tooltip.innerHTML = lines.join('');
      tooltip.style.display = 'block';
      // The SVG is rendered at native pixel width (W), not scaled to fit wrap, so
      // gx is already in the same coordinate space as wrap's scrollable content —
      // no need to rescale by clientWidth (that was the bug: it placed bars near
      // the right edge as if the chart were compressed to fit the visible viewport,
      // so on mobile — where the chart scrolls horizontally — the tooltip for those
      // bars popped up far to the left of the bar itself). Instead, clamp the
      // tooltip to the currently-visible scrolled window so it always lands next
      // to the bar the person is looking at, without running off either edge.
      var contentLeft = gx + groupW / 2 - 75;
      var viewLeft = wrap.scrollLeft || 0;
      var viewRight = viewLeft + wrap.clientWidth;
      var left = Math.max(viewLeft + 2, Math.min(contentLeft, viewRight - 152));
      left = Math.max(2, Math.min(left, (wrap.scrollWidth || wrap.clientWidth) - 152));
      tooltip.style.left = left + 'px';
      tooltip.style.top = '0px';
    }
    function hideTip(){ tooltip.style.display = 'none'; }
    hit.addEventListener('pointerenter', showTip);
    hit.addEventListener('focus', showTip);
    hit.addEventListener('pointerleave', hideTip);
    hit.addEventListener('blur', hideTip);
    svg.appendChild(hit);
  });

  wrap.appendChild(svg);
  card.appendChild(wrap);
  return card;
}

