  hero.className = 'hero';
  hero.innerHTML = '<img class="hero-mascot" src="' + LOGO_BULLDOG + '" alt="">' +
    '<img class="hero-crest" src="' + LOGO_CREST + '" alt="Big Dogs Tour crest">' +
    '<div class="kicker">Big Dogs Tour — Bloodhounds v Retrievers</div>' +
    '<h2>The Stats</h2>' +
    '<p>Every result, record and leaderboard from the master playbook — browse by section on the left, or filter every table at once with the box above.</p>';
  el.appendChild(hero);
  initHeroSpotlight(hero);

  var landingHead = document.createElement('div');
  landingHead.className = 'landing-heading';
  landingHead.textContent = 'Explore the tour';
  el.appendChild(landingHead);

  var landingGrid = document.createElement('div');
  landingGrid.className = 'landing-grid';
