  rohCard.innerHTML = '<h4>Roll of Honour</h4>';
  var rohList = document.createElement('ul');
  rohList.className = 'roh-list';
  (DASH.roll_of_honour||[]).forEach(function(row){
    var li = document.createElement('li');
    li.innerHTML = '<span class="roh-year">'+esc(row[0])+'</span>' +
      '<span class="roh-winner">'+esc(row[1])+'</span>' +
      (row[2] ? '<span class="roh-second">2nd: '+esc(row[2])+'</span>' : '');
    rohList.appendChild(li);
  });
  rohCard.appendChild(rohList);
  two.appendChild(rohCard);

  var rightCol = document.createElement('div');
  var winsItems = (DASH.most_big_dog_wins||[]).map(function(row){ return {label: row[0], value: row[1]}; });
  rightCol.appendChild(buildBarList('Most Big Dog Wins', null, winsItems));
  var ptsItems = (DASH.most_rc_points||[]).map(function(row){ return {label: row[0], value: row[1]}; });
  rightCol.appendChild(buildBarList('Most Ryder Cup Points', null, ptsItems));

  two.appendChild(rightCol);
