// The overall record between the two sides, all-time — a small scoreboard for the
// top of the Ryder Cup Results page, pulled from RC Results' "Series summary" block.
function buildScoreboard(){
  var sh = SHEETS['RC Results'];
  if (!sh || !sh.blocks[1]) return null;
  var sb = sh.blocks[1];
  var mi = sb.headers.indexOf('Metric'), bi = sb.headers.indexOf('Bloodhounds'), ri = sb.headers.indexOf('Retrievers');
  if (mi === -1 || bi === -1 || ri === -1) return null;

  function metric(prefix){
    var row = sb.rows.filter(function(r){
      return String(r[mi]).toLowerCase().indexOf(prefix.toLowerCase()) === 0;
    })[0];
    return row ? {bh: row[bi], rt: row[ri]} : null;
  }

  var wins = metric('Wins');
  if (!wins) return null;
  var outright = metric('of which outright');
  var retained = metric('of which retained');

  var leader = 'Level';
  if (Number(wins.bh) > Number(wins.rt)) leader = 'Bloodhounds lead';
  else if (Number(wins.rt) > Number(wins.bh)) leader = 'Retrievers lead';

  var wrap = document.createElement('div');
  wrap.className = 'series-scoreboard';
  wrap.innerHTML =
    '<div class="st-team bh"><div class="st-name">Bloodhounds</div><div class="st-score">' + esc(wins.bh) + '</div>' +
      (outright ? '<div class="st-sub">' + esc(outright.bh) + ' outright &middot; ' + esc(retained ? retained.bh : 0) + ' retained</div>' : '') +
    '</div>' +
    '<div class="st-divider"><div class="sd-label">Cups won</div><div class="sd-leader">' + esc(leader) + '</div></div>' +
    '<div class="st-team rt"><div class="st-name">Retrievers</div><div class="st-score">' + esc(wins.rt) + '</div>' +
      (outright ? '<div class="st-sub">' + esc(outright.rt) + ' outright &middot; ' + esc(retained ? retained.rt : 0) + ' retained</div>' : '') +
    '</div>';
  return wrap;
}

// "All Editions" — one clickable card per tour (year, location, final score, colored
// by winner), with a click-through detail panel showing that year's match-by-match
// results grouped by round, pulled from the raw RC Matches log.
function buildEditionsSection(){
  var rcResults = SHEETS['RC Results'], rcMatches = SHEETS['RC Matches'];
  if (!rcResults || !rcMatches || !rcResults.blocks[0] || !rcMatches.blocks[0]) return null;

  var rb = rcResults.blocks[0];
  var yi = rb.headers.indexOf('Year'), li = rb.headers.indexOf('Location'),
      bi = rb.headers.indexOf('Final BH'), ri = rb.headers.indexOf('Final RT'),
      wi = rb.headers.indexOf('Winner / holder');
  if (bi === -1 || ri === -1) return null;

  var editions = [];
  rb.rows.forEach(function(r){
    if (r[bi] !== '' && r[bi] !== null && r[bi] !== undefined){
      editions.push({year: r[yi], location: r[li], bh: r[bi], rt: r[ri], winner: wi !== -1 ? r[wi] : ''});
    }
  });
  if (!editions.length) return null;

  var mb = rcMatches.blocks[0], mh = mb.headers;
  var myi = mh.indexOf('Year'), mri = mh.indexOf('Round (1-3)'), mfi = mh.indexOf('Format'),
      mbh1 = mh.indexOf('BH player 1'), mbh2 = mh.indexOf('BH player 2'),
      mrt1 = mh.indexOf('RT player 1'), mrt2 = mh.indexOf('RT player 2'),
      mres = mh.indexOf('Result'), mmar = mh.indexOf('Margin (3&2, 1UP, A/S)'), mstat = mh.indexOf('Status');

  var wrap = document.createElement('div');
  wrap.className = 'editions-wrap';
  var headEl = document.createElement('div');
  headEl.className = 'landing-heading';
  headEl.textContent = 'All results — click a year for the match-by-match detail';
  wrap.appendChild(headEl);

  var grid = document.createElement('div');
  grid.className = 'editions-grid';
  var detail = document.createElement('div');
  detail.className = 'edition-detail';

  var roundNames = {1: 'Round I', 2: 'Round II', 3: 'Round III'};

  function showEdition(ed, cardEl, scrollToDetail){
    grid.querySelectorAll('.edition-card').forEach(function(c){ c.classList.toggle('selected', c === cardEl); });
    var matches = myi !== -1 ? mb.rows.filter(function(r){ return r[myi] === ed.year; }) : [];
    var rounds = {};
    matches.forEach(function(r){
      var rn = mri !== -1 ? r[mri] : 0;
      (rounds[rn] = rounds[rn] || []).push(r);
    });
    var roundNums = Object.keys(rounds).map(Number).sort(function(a,b){ return a - b; });

    var winnerLine = ed.winner ? (ed.winner + (/^(bloodhounds|retrievers)$/i.test(ed.winner) ? ' won' : '')) : '';
    var html = '<h3>' + esc(ed.year) + ' · ' + esc(ed.location || '') + '</h3>' +
      (winnerLine ? '<div class="ed-subtitle">' + esc(winnerLine) + '</div>' : '') +
      '<div class="ed-summary"><div><div class="es-label">Final score</div><div class="es-value">' +
      '<span class="bh">' + esc(ed.bh) + '</span><span class="sep"> – </span><span class="rt">' + esc(ed.rt) + '</span>' +
      '</div></div></div>';

    if (!roundNums.length){
      html += '<p style="color:var(--ink-soft);font-size:13px;margin:0;">No match-by-match log for this tour.</p>';
    }
    roundNums.forEach(function(rn){
      html += '<div class="match-day"><div class="match-day-label">' + esc(roundNames[rn] || ('Round ' + rn)) + '</div>';
      rounds[rn].forEach(function(r){
        var bhP = [mbh1 !== -1 ? r[mbh1] : '', mbh2 !== -1 ? r[mbh2] : ''].filter(Boolean).join(' & ');
        var rtP = [mrt1 !== -1 ? r[mrt1] : '', mrt2 !== -1 ? r[mrt2] : ''].filter(Boolean).join(' & ');
        var res = mres !== -1 ? r[mres] : '', status = mstat !== -1 ? r[mstat] : '';
        var cls = 'halved', label = 'Halved';
        if (status === 'Abandoned'){ cls = 'halved'; label = 'Rained off'; }
        else if (res === 'Bloodhounds'){ cls = 'bh'; label = 'BH'; }
        else if (res === 'Retrievers'){ cls = 'rt'; label = 'RT'; }
        var margin = (mmar !== -1 && r[mmar] && status !== 'Abandoned') ? (' (' + esc(r[mmar]) + ')') : '';
        html += '<div class="match-row"><div class="match-bh">' + esc(bhP) + '</div>' +
          '<div><div class="match-result ' + cls + '">' + esc(label) + margin + '</div>' +
          '<div class="match-format">' + esc(mfi !== -1 ? r[mfi] : '') + '</div></div>' +
          '<div class="match-rt">' + esc(rtP) + '</div></div>';
      });
      html += '</div>';
    });
    detail.innerHTML = html;
    detail.classList.add('show');
    // Call synchronously rather than deferring via requestAnimationFrame: reading
    // getBoundingClientRect() inside scrollFullyIntoView already forces layout to
    // flush, so the rAF wasn't buying accuracy - and deferring a smooth-scroll
    // out of the click handler's own call stack is exactly what makes some
    // mobile browsers (notably iOS Safari) silently drop it, since they tie a
    // programmatic smooth scroll to the user-gesture that triggered it.
    if (scrollToDetail){
      scrollFullyIntoView(detail);
    }
  }

  editions.forEach(function(ed, i){
    var card = document.createElement('button');
    card.type = 'button';
    var cls = 'edition-card ';
    if (/^bloodhounds$/i.test(ed.winner)) cls += 'bh-win';
    else if (/^retrievers$/i.test(ed.winner)) cls += 'rt-win';
    else cls += 'tie';
    card.className = cls;
    card.innerHTML = '<div class="ed-year">' + esc(ed.year) + '</div>' +
      '<div class="ed-loc">' + esc(ed.location || '') + '</div>' +
      '<div class="ed-score"><span class="bh">' + esc(ed.bh) + '</span><span class="sep">–</span><span class="rt">' + esc(ed.rt) + '</span></div>';
    card.addEventListener('click', function(){ showEdition(ed, card, true); });
    grid.appendChild(card);
    if (i === editions.length - 1) showEdition(ed, card, false); // open the most recent tour by default, no auto-scroll
  });

  wrap.appendChild(grid);
  wrap.appendChild(detail);
  return wrap;
}

// Sections whose first sheet is otherwise just a plain data table dropped straight
// into the section, with nothing of its own to orient a visitor first — these get a
// synthetic "Overview" page prepended (see buildSectionHub) instead of landing on
// that raw table. Kept to just "records": with only two subpages, an in-between
// index page for h2h/placings/alltime/log added a click without adding much a
// visitor couldn't already see from the section banner and the tab strip right
// below it — records earns its own page with a genuine headline stat and four
// subpages to route between. "results" has its own bespoke landing (below);
// "stableford", "trophies" and "players" each already open on a custom visual
// (Explorer / Trophy Cabinet / roster grid) that already reads as a distinct hub.
var HUB_SECTIONS = { records: 1 };

// The id/label pairs a paged section is made of — shared between building the
// page itself and building the sidebar's subnav, so the two never drift apart.
function getSectionPages(sec){
  var pages = [];
  if (sec.id === 'results'){
    pages.push({ id: 'landing', label: 'Overview' });
    pages.push({ id: 'editions', label: 'All Results' });
  }
  if (HUB_SECTIONS[sec.id]) pages.push({ id: 'hub', label: 'Overview' });
  sec.sheets.forEach(function(key){
    // RC Results no longer gets its own tab — its chart lives on the Ryder Cup
    // Results landing page, and its Series Summary table at the foot of the
    // Tour by Tour (Results Summary) page.
    if (sec.id === 'results' && key === 'RC Results') return;
    pages.push({ id: key, label: TAB_LABELS[key] || (SHEETS[key] && SHEETS[key].title) || key });
  });
  return pages;
}

